// The face domain's drawing: the ears, the head, and the face with its eyes, nose, mouth, blush and scar. Port of
// character.py's `_ear_span` to `_face` (the ear block at 12239, the head at 12422, the eye code at 12477 to 12813, the blush
// at 12978, the nose at 13024 and `_face` at 13094). The beard, the glasses, the goggles and the blindfold are in
// face-wear.ts. Function names are the Python ones in camelCase; every expression keeps Python's evaluation order. Numbers
// reach the text only through the `fmt*` kernel functions. The ear's traced tables are in face-tables.ts, generated by
// harness/ts_port/gen_face_tables.py.

import { OUTLINE, curve, interiorW, outlineW, quadPoint, soft as isSoft, strokeW } from "./character.ts";
import { hexToRgb01, rgb01ToHex, shade, tint } from "./colorutil.ts";
import {
  EAR_BOT_Y,
  EAR_TOP_Y,
  EYE_ASPECT,
  eyeBuild,
  eyePlacement,
  headEdgeX,
  headPaths,
  hairstyleFor,
  brow,
  mirror,
} from "./core-head.ts";
import { EAR_ARC, EAR_ARC_START, EAR_FOLD, EAR_FOLD_START } from "./face-tables.ts";
import type { CharacterParams, FaceStyle } from "./params.ts";
import { powRounded } from "./core-limbs-pow.ts";
import { BadValue, PyError, fmt1, fmt2, fmt3, pyCos, pyDiv, pyHypot, pyInt, pyMax, pyMin, pySin, pySqrt, radians, truthy } from "./pynum.ts";
import { pyValueRepr } from "./pyvalue.ts";
import { type Skeleton, faceBuild } from "./skeleton.ts";
import type { Chain, Point, Segment } from "./tables.ts";

/**
 * `f"{f.iris_aspect:.3f}"`. A string where a number belongs is a `ValueError` here ("Unknown format code"), not the `TypeError` that
 * arithmetic on it would give; a list or `None` is a `TypeError` either way, which `fmt3` of the stand-in raises.
 */
const fmt3Field = (value: number): string => {
  const v: unknown = value;
  if (v instanceof BadValue && typeof v.original === "string") {
    throw new PyError("ValueError", "Unknown format code 'f' for object of type 'str'");
  }
  return fmt3(value);
};

/**
 * `f"{x}"` of a colour field: the text itself when it is a string. A link or a model's request can put an int, a flag or a
 * list in a colour field and Python writes its `str()` into the drawing where nothing calls `shade()` on it first.
 */
export const pyStr = (v: unknown): string => (typeof v === "string" ? v : pyValueRepr(v));

// ---------------------------------------------------------------------------------------------------------
// The ears

// How far the ear stands clear of the skull at its widest, in head radii.
//
// The canon's own ear is 0.263 r wide, and that is not transferable as it
// stands: it sticks out past a cheek sitting at 0.632 r, where ours sits at
// 0.81 (adult) to 0.94 (chibi), so the canon's whole head-plus-ear reaches 0.895
// r and our bare skull is already past that at the chibi. Our head being wide
// against the canon's is the open residual under gap 2, not something the ear
// can fix, so the ear takes a width that reads at our scale rather than one that
// matches a silhouette we cannot match anyway.
export const EAR_OUT = 0.17;
// The ear is the same size against the head at both builds, deliberately. A
// child's ear really is larger against its skull than an adult's, and that was
// in here for a round as a shrink on the build, but the span above is measured
// off the *adult* reference, so a shrink made the one build the number came from
// the one build that did not reproduce it: the adult came out 12% short while
// the chibi got the canon figure exactly.
//
// **Retraction.** This used to say there was no chibi ear to measure, both cuts
// covering it. There is: `ref/satoshi-chibi.jpg` draws the viewer-right one
// clear of the hair, and the owner's crop of it is `ref/satoshi-ear.png`.
// Measured (`out/ear2/`), the chibi's ear runs 0.024 to 0.614 head radii against
// the adult's 0.03 to 0.49, so it really is about 30% taller against the skull,
// the way anatomy says. The span here is still the adult's and the shrink is
// still gone: resolving that into a build-riding span is a placement change and
// a separate decision from the shape below, which is what the trace is used for.

// The ear's outline and its one inner fold, traced off the canon chibi and held
// in the ear's own frame rather than in head radii: y runs 0 at the top attach to
// 1 at the bottom, and x runs 0 on the chord between them to 1 at the widest
// stand-out. That is what makes the trace a *shape* and leaves where the ear
// sits and how far it stands out to `_EAR_TOP_Y`, `_EAR_BOT_Y` and `_EAR_OUT`
// above, which are measured off the adult and should not be spent on this.
//
// Simplified to the finest level with no edge under two stroke widths at either
// build, the same rule the hair silhouette settled on. The rim's own weight sets
// the floor for the outline and 0.55 of it for the fold, so the fold gets to
// keep more detail than the rim does.
//
// (`EAR_ARC_START` and `EAR_ARC` are in face-tables.ts.)
//
// The antihelix, which the canon draws as one stroke shaped like a question
// mark: an upper crescent that turns back on itself and runs down into a hook.
// Isolating it took three readings. It is not a separate piece of ink, since it
// runs into the rim at the top, so connectivity does not find it; and it is not
// the second run of ink along a row either, since a row-scan hops between the
// crescent, the hook and the rim and comes out a zigzag lying on none of them.
// What works is eroding the silhouette until the rim, which is its boundary by
// definition, has nothing left, while a stroke drawn across the middle survives.
//
// Its x is normalised across its own width rather than shared with the rim's.
// The canon's fold reaches a third of the ear's stand-out *left* of the attach
// chord, which our ear has no room for: our chord is a straight line between two
// points on the skull, and a skull is convex, so it bulges out past the chord
// everywhere in between. The canon's ear overlaps the cheek and ours is welded
// to it. So the two constants below say which band of the ear's width the fold
// lands in, and the trace says only what shape it is inside that band.
//
// (`EAR_FOLD_START` and `EAR_FOLD` are in face-tables.ts.)
//
// Where that band sits, as a share of the stand-out: inner edge, then width.
// Solved rather than picked (`out/ear2/band.py`). Every point of the fold has to
// clear the skull on one side and the rim on the other by a crease's own stroke
// width, at both builds, which is two inequalities per point and linear in these
// two numbers; this is the widest band that satisfies all of them, and it leaves
// the inner edge with a hundredth of slack. Three candidate bands were rendered
// first and the chibi tiles were not distinguishable by eye, which is what makes
// this worth solving instead: the eye had nothing to go on and the constraint
// does. The band picked by eye turned out to be infeasible at the adult.
export const EAR_FOLD_IN = 0.3;
export const EAR_FOLD_SPAN = 0.45;

/** Where the ear joins the skull, top and bottom, on the right side. */
export function earSpan(build: number): readonly [Point, Point] {
  return [
    [headEdgeX(EAR_TOP_Y, build), EAR_TOP_Y],
    [headEdgeX(EAR_BOT_Y, build), EAR_BOT_Y],
  ];
}

/**
 * Maps a traced (along, out) onto the skull, in head radii.
 *
 * `along` runs the attach chord and `out` is measured straight along x, not
 * perpendicular to the chord. The chord is not near vertical, 16 degrees off
 * at the chibi and 19 at the adult, so the two are not the same thing: x is
 * the deliberate one, because `_EAR_OUT` is defined as how far the ear stands
 * clear of the skull sideways, and a perpendicular offset would shorten it by
 * the cosine and by a different amount at each build. Riding the chord rather
 * than a fixed x is what welds the traced shape to a skull whose own width
 * moves with the build.
 */
export function earPlace(build: number): (pt: Point) => Point {
  const [[topX, topY], [botX, botY]] = earSpan(build);
  return (pt: Point): Point => {
    const [along, out] = pt;
    return [topX + (botX - topX) * along + out * EAR_OUT, topY + (botY - topY) * along];
  };
}

/**
 * The ear's outer contour, top attach to bottom attach, on the right side.
 *
 * The helix is the only thing this draws, traced off the canon chibi. What was
 * here before was two quadratics out to a widest point and back, which is the
 * right idea and the wrong curve: the canon's rim leaves the top attach much
 * faster than a single control can, holds its width through the middle of the
 * ear rather than peaking, and comes back in along the lobe. Four segments,
 * which is the finest the line weight supports.
 */
export function earOuter(build: number): Chain {
  const place = earPlace(build);
  return [place(EAR_ARC_START), EAR_ARC.map(([c, e]): Segment => [place(c), place(e)])];
}

/**
 * Ears, drawn *under* the head so the face's own outline runs across them.
 *
 * That is the canon's construction, and looking at it beside ours was what
 * settled it (`out/ear2/depth.png`, the owner's call on 2026-08-07): the
 * reference draws one unbroken heavy line down the side of the face and the
 * ear behind it, with only the part past that line showing. Drawn over the
 * head instead, the ear's rim runs into the face's outline and joins it, and
 * the two read as one silhouette that happens to bulge rather than as an ear
 * behind a face.
 *
 * So what is visible here is the arc outside the skull and nothing else. The
 * fill still closes on a straight chord between the attach points, but the
 * chord and everything inboard of it is now painted over by the head; it is
 * there to give the sliver outside the skull something to be part of. Only the
 * outer arc carries a stroke, and the arc meets the skull exactly at both
 * attach points, so it emerges from the face's outline rather than crossing
 * it.
 */
export function ears(sk: Skeleton, p: CharacterParams): string {
  if (truthy(hairstyleFor(p.hairstyle).covers_ears)) return "";
  const cx = sk.head_cx;
  const cy = sk.head_cy;
  const r = sk.head_r;
  const sw = strokeW(sk);
  const [start, segments] = earOuter(faceBuild(sk));
  const place = earPlace(faceBuild(sk));

  // The antihelix, traced with the rim. It stops well short of both ends, as
  // the canon's does: run it to the lobe and it closes into a second outline,
  // which reads as a hole rather than as the turn of a rim.
  const fold = (pt: Point): Point => place([pt[0], EAR_FOLD_IN + pt[1] * EAR_FOLD_SPAN]);

  const creaseStart = fold(EAR_FOLD_START);
  const crease = EAR_FOLD.map(([c, e]): Segment => [fold(c), fold(e)]);

  const parts: string[] = [];
  for (const side of [-1, 1]) {
    const [earStart, earSegments] = side > 0 ? [start, segments] : mirror(start, segments);
    const [cStart, cSegments] = side > 0 ? [creaseStart, crease] : mirror(creaseStart, crease);
    parts.push(`<path d="${curve(cx, cy, r, earStart, earSegments)}" fill="${pyStr(p.skin_tone)}" />`);
    parts.push(
      `<path d="${curve(cx, cy, r, earStart, earSegments, false)}" fill="none" ` +
        `stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(sw))}" stroke-linecap="round" />`,
    );
    parts.push(
      `<path d="${curve(cx, cy, r, cStart, cSegments, false)}" fill="none" ` +
        `stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(sw, 0.55))}" stroke-linecap="round" />`,
    );
  }
  return parts.join("");
}

// ---------------------------------------------------------------------------------------------------------
// The head

// The face's outline in a dark tone of the skin. A shading gradient toward the face's
// edge was tried and removed (owner's blind pairs, 2026-10-16: it read as dirt at the
// zoomed size), so the face stays one flat surface as `_head` says.
export const SOFT_FACE_LINE_VALUE = 0.4;

/**
 * The face is deliberately the one flat surface on the figure.
 *
 * A shadow down the far cheek is what the cel-shaded look would call for, and
 * it was tried, but at this level of simplification it reads as a smudge or a
 * dirty mark rather than as a turn away from the light: there is no nose or
 * brow ridge for it to fall off, so it has nothing to explain it. The hair
 * already darkens one side of the head, which is enough.
 */
export function head(sk: Skeleton, p: CharacterParams): string {
  const [fill, silhouette, underChin] = headPaths(sk);
  const parts = [`<path d="${fill}" fill="${pyStr(p.skin_tone)}" />`];
  const soft = isSoft(p);
  const line = soft ? shade(p.skin_tone, SOFT_FACE_LINE_VALUE) : OUTLINE;

  // The outline is drawn in two weights rather than as one closed stroke. Around
  // the skull and cheeks it is silhouette, so it carries full weight. Under the
  // chin it is not: the throat stands in front of the underside of the jaw, so a
  // full-weight line there reads as the whole jaw seen edge-on instead of as the
  // front of it. Splitting at the two lower corners of the shape is what lets
  // the same point data carry both. It is an outline at 0.6 of the silhouette's
  // weight, the ratio it had before D1's split: drawn as an interior line it
  // fell to 0.44 and read as a different pen (the owner, 2026-09-27,
  // `harness/detail/chin_weight.py`).
  const sw = strokeW(sk);
  parts.push(
    `<path d="${silhouette}" fill="none" stroke="${line}" stroke-width="${fmt2(outlineW(sw))}" ` + `stroke-linecap="round" />`,
  );
  parts.push(
    `<path d="${underChin}" fill="none" stroke="${line}" stroke-width="${fmt2(outlineW(sw, 0.6))}" ` + `stroke-linecap="round" />`,
  );
  return parts.join("");
}

// ---------------------------------------------------------------------------------------------------------
// The eyes

// (`_EYE_ASPECT`, how wide the aperture runs against its own height, is in core-head.)

// How far the iris travels at a full look to one side, in eye radii, or the room the aperture
// leaves it if that is less (`_eye`).
export const GAZE_TRAVEL = 0.34;

// The aperture outline's weight, upper half-circle and lower half-circle
// alike. Used to carry two different multipliers here, 0.85 for the whole
// aperture and a heavier 1.6 redrawn over just the upper lid, the canon's
// own heavy-lash-line convention; the owner's call on 2026-08-11 was to
// drop that asymmetry rather than tune it, so both halves read as one
// weight of line now.
export const EYE_OUTLINE_W = 0.85;

// How much bigger the pupil gets, as a fraction of the iris radius, at the
// realistic build, on top of `_eye()`'s own default of 0.40. Global rather
// than per-character or a `FaceStyle` field, since gap 11 read this as a
// house-wide construction choice, not something either preset's own numbers
// ever varied; build-gated the same way everything else in this pass is, so
// the chibi's own pupil is untouched. Picked by render sweep against
// `ref/satoko-real.jpg`.
export const PUPIL_REALISTIC_GROW = 0.1;

/**
 * The eye aperture's four quadratics, in eye radii about the eye's center
 * with x measured outward from the face center: inner corner to apex, apex to
 * outer corner (the upper lid), outer corner to base, base to inner corner.
 *
 * Each control point sits at the extreme of its half and is slid along x by
 * `eye_corner`: sitting directly over a corner it gives an elliptical quarter
 * and the corner reads round, pulled toward the middle the curve leaves the
 * corner shallowly and reads pointed.
 */
export function eyeQuads(er: number, f: FaceStyle): [Point, Point, Point][] {
  const w = er * f.eye_width * EYE_ASPECT;
  const top = er * f.eye_openness;
  const bot = er * f.eye_lower_lid;
  const tilt = er * f.eye_tilt * 0.3;
  const reach = 0.55 * f.eye_corner;

  const inner: Point = [-w, tilt];
  const apex: Point = [w * 0.05, -top];
  const outer: Point = [w, -tilt];
  const base: Point = [-w * 0.1, bot];

  const ctrl = (corner: Point, toward: Point, y: number): Point => [corner[0] + (toward[0] - corner[0]) * reach, y];

  return [
    [inner, ctrl(inner, apex, -top), apex],
    [apex, ctrl(outer, apex, -top), outer],
    [outer, ctrl(outer, base, bot), base],
    [base, ctrl(inner, base, bot), inner],
  ];
}

/** Eye aperture as a closed almond (`_eye_quads`), plus its upper lid on its own, mirrored per side. */
export function eyeShape(ex: number, ey: number, er: number, side: number, f: FaceStyle): [string, string] {
  const pt = (p: Point): string => `${fmt1(ex + side * p[0])} ${fmt1(ey + p[1])}`;

  const q = eyeQuads(er, f);
  const lid = `M ${pt(q[0]![0])} Q ${pt(q[0]![1])} ${pt(q[0]![2])} Q ${pt(q[1]![1])} ${pt(q[1]![2])}`;
  const d = lid + ` Q ${pt(q[2]![1])} ${pt(q[2]![2])} Q ${pt(q[3]![1])} ${pt(q[3]![2])} Z`;
  return [d, lid];
}

// The eye's lining (step D2 of `docs/detail-plan.md`, the owner's pick from
// `harness/detail/eye_study.py`, 2026-09-27), in the spirit of
// `ref-local/katherina_grok_real/`: the upper lash is the one heavy line in the
// face, a filled band along the lid, thin at the inner corner and thickening
// toward the outer one, where it ends in a flick past the corner. The lower
// edge is only a faint line, with a short lash at its outer corner; unlined,
// the white bled into pale skin. Lash thickness in eye radii, flick length too;
// its angle in degrees above the lid's own direction at the corner.
export const LASH_INNER = 0.05;
export const LASH_OUTER = 0.24;
export const LASH_EASE = 1.4;
// Where the lash has grown to its easing curve from nothing at the inner
// corner, as a share of the lid.
export const LASH_ONSET = 0.12;
export const LASH_FLICK = 0.4;
export const LASH_FLICK_ANGLE = 28.0;
// How far along the lower lid, outer corner toward the base, the lower lash
// reaches, as the outer quadratic's parameter.
export const LOWER_LASH_REACH = 0.5;
export const LID_SAMPLES = 16;
// The top of the iris in a darker flat band, cut this far above the iris's
// centre (a share of the coloured disc's radius), at this `shade()`.
export const IRIS_BAND_CUT = 0.25;
export const IRIS_BAND_SHADE = 0.68;
// The white of the eye where the upper lid shades it (`FaceStyle.lid_shadow`).
export const SCLERA_SHADOW = "#c2c2c8";

/** Points along the aperture's quadratics `first` to `last` inclusive. */
export function lidPoints(quads: readonly (readonly [Point, Point, Point])[], first: number, last: number): Point[] {
  const pts: Point[] = [];
  for (let i = first; i <= last; i++) {
    const start = i === first ? 0 : 1;
    const q = quads[i] as readonly [Point, Point, Point];
    // `pts += [...]` extends the list that is `pts`; a comprehension per quadratic, `k / _LID_SAMPLES` (16, never zero).
    for (let k = start; k <= LID_SAMPLES; k++) pts.push(quadPoint(q[0], q[1], q[2], k / LID_SAMPLES));
  }
  return pts;
}

/**
 * The upper lash as a closed outline in eye-local units: its upper edge
 * along the lid pushed outward by the lash's thickness, the flick's tip, and
 * back along the lid half a line inside it, so the lash covers where the
 * aperture's edge is.
 */
export function eyeLash(er: number, f: FaceStyle, edge_w: number, reach: number | null = null): Point[] {
  const lid = lidPoints(eyeQuads(er, f), 0, 1);
  const n = lid.length - 1;
  const outer = LASH_INNER + (LASH_OUTER - LASH_INNER) * f.lash;
  let flick = LASH_FLICK * f.lash;
  let up: Point[] = [];
  const down: Point[] = [];
  for (let i = 0; i < lid.length; i++) {
    const [x, y] = lid[i] as Point;
    const a = lid[pyMax(0, i - 1)] as Point;
    const b = lid[pyMin(n, i + 1)] as Point;
    const tx = b[0] - a[0];
    const ty = b[1] - a[1];
    // `math.hypot(tx, ty) or 1.0`: an operand, so 1.0 only when the length is zero.
    const hyp = pyHypot(tx, ty);
    const tl = truthy(hyp) ? hyp : 1.0;
    let nx = ty / tl;
    let ny = -tx / tl;
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }
    // `i / n`: the lid has 33 points, so `n` is 32.
    const s = i / n;
    // `s ** _LASH_EASE` (a fractional power): the engine's `Math.pow` is an ulp off the C library's on 77 of 128 recorded
    // calls of this function, so the correctly rounded `powRounded` of core-limbs-pow.ts stands in for `pyPow` here.
    let t = er * (LASH_INNER + (outer - LASH_INNER) * powRounded(s, LASH_EASE));
    if (s < LASH_ONSET) t *= s / LASH_ONSET;
    t = pyMax(edge_w * 0.5, t);
    up.push([x + nx * t, y + ny * t]);
    down.push([x - nx * edge_w * 0.5, y - ny * edge_w * 0.5]);
  }
  let tx = (lid[n] as Point)[0] - (lid[n - 3] as Point)[0];
  let ty = (lid[n] as Point)[1] - (lid[n - 3] as Point)[1];
  const hyp2 = pyHypot(tx, ty);
  const tl = truthy(hyp2) ? hyp2 : 1.0;
  tx = tx / tl;
  ty = ty / tl;
  const ang = radians(-LASH_FLICK_ANGLE);
  const fx = tx * pyCos(ang) - ty * pySin(ang);
  const fy = tx * pySin(ang) + ty * pyCos(ang);
  // Shortened, never lengthened, so its tip stays `reach` from the eye's centre:
  // a flick running past the face's edge reads as the eye itself overflowing
  // the face, which the owner found creepy (2026-09-27).
  if (reach !== null && fx > 0.0) {
    flick = pyMax(0.0, pyMin(flick, pyDiv(reach - (lid[n] as Point)[0], fx * er)));
  }
  const tip: Point = [
    (lid[n] as Point)[0] + fx * er * flick,
    (lid[n] as Point)[1] + fy * er * flick - er * outer * 0.5,
  ];
  if (reach !== null) {
    // The lash's thickness at the outer corner reaches past the corner itself,
    // so an eye near the face's edge could put its upper edge over it.
    const r = reach;
    up = up.map(([x, y]): Point => [pyMin(x, r), y]);
  }
  return [...up, tip, ...[...down].reverse()];
}

/** One eye, on `side` (-1 left, 1 right), drawn at `(ex, ey)` with radius `er`. */
export function eye(
  ex: number,
  ey: number,
  er: number,
  side: number,
  f: FaceStyle,
  eye_color: string,
  sw: number,
  pupil_ratio = 0.4,
  reach: number | null = null,
  soft = false,
): string {
  const [d] = eyeShape(ex, ey, er, side, f);
  const clipId = `eye-${side < 0 ? "l" : "r"}`;

  // Size the iris off whichever half-axis of the aperture is smaller, so a
  // narrow or half-lidded eye keeps white at its corners instead of filling
  // solid with color. Everything inside the eye is placed off the iris, and
  // the iris off the aperture's own center. It rides high in the aperture:
  // the canon tucks the iris up under the lash line, and white showing above
  // it reads as a startled stare rather than a resting gaze.
  const irisR = f.iris_size * pyMin(er * f.eye_width, (er * (f.eye_openness + f.eye_lower_lid)) / 2);
  const irisCy = ey + (er * (f.eye_lower_lid - f.eye_openness)) / 2 - irisR * 0.1;

  // Still clipped to the aperture, so a low lid crops the iris rather than
  // letting it hang over the lash line.
  const parts = [`<defs><clipPath id="${clipId}"><path d="${d}" /></clipPath></defs>`];
  // Unstroked: the lining is drawn over the iris below, a heavy lash above
  // and a faint line below (`_LASH_INNER` and the rest). This undoes the
  // 2026-08-11 call that gave both halves one weight, by the owner's pick
  // of 2026-09-27.
  parts.push(`<path d="${d}" fill="white" stroke="none" />`);
  parts.push(`<g clip-path="url(#${clipId})">`);
  if (truthy(f.lid_shadow)) {
    // The aperture again in grey, then the same shape moved down over it in white: what
    // is left of the grey is a band along the upper lid, as deep as the move.
    const drop = f.lid_shadow * er * (f.eye_openness + f.eye_lower_lid);
    parts.push(`<path d="${d}" fill="${SCLERA_SHADOW}" stroke="none" />`);
    parts.push(`<path d="${d}" fill="white" stroke="none" transform="translate(0 ${fmt2(drop)})" />`);
  }
  // Looking sideways moves the iris and everything drawn on it, and nothing else:
  // the lids and lashes stay put, and the aperture's clip crops what overhangs.
  //
  // The iris stays inside the white: how far it can travel is the room the aperture leaves
  // it (its half-width less the iris's own radius), and a look never asks for more than
  // that. Past it the clip would crop the iris at the corner and it would seem to slide
  // under the skin instead of turning in the eye. The iris's rest spot (`iris_inset`)
  // eases into the look, so at a full look both eyes sit at the same offset from their
  // centres, the way two eyes turn together, and the one already tucked into the corner
  // on that side stays there instead of being pushed past it.
  const room = pyMax(0.0, er * f.eye_width * EYE_ASPECT - irisR);
  const look = pyMax(-1.0, pyMin(1.0, f.gaze));
  const atRest = -side * f.iris_inset * room;
  const ix = ex + atRest * (1.0 - Math.abs(look)) + look * pyMin(er * GAZE_TRAVEL, room);
  // Canon iris: a rim of the eye color's own darker tone around the color,
  // with a distinct near-dark pupil inside that. Three flat tones, which is
  // what makes the eye read at a glance where a single disc read as a bead.
  // `f.iris_aspect != 1.0`: a value that is not a number (a `BadValue`) is not equal to it either, as in Python.
  const stretch = f.iris_aspect !== 1.0;
  if (stretch) {
    // Scaled about the iris's own centre, so the rim, the band and the pupil are
    // stretched together. The highlights are drawn after it, round.
    parts.push(
      `<g transform="translate(0 ${fmt2(irisCy)}) scale(1 ${fmt3Field(f.iris_aspect)}) ` + `translate(0 ${fmt2(-irisCy)})">`,
    );
  }
  parts.push(`<circle cx="${fmt1(ix)}" cy="${fmt1(irisCy)}" r="${fmt1(irisR)}" fill="${shade(eye_color, 0.45)}" />`);
  let irisFill = eye_color;
  if (soft) {
    // The colour darker at the top, where the lid shades it, and lighter at the
    // bottom, where light comes through: the one gradient that makes a flat disc
    // read as a glassy iris.
    const gradId = `iris-grad-${side < 0 ? "l" : "r"}`;
    parts.push(
      `<defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">` +
        `<stop offset="0" stop-color="${shade(eye_color, 0.62)}" />` +
        `<stop offset="0.55" stop-color="${eye_color}" />` +
        `<stop offset="1" stop-color="${tint(eye_color, 0.38)}" /></linearGradient></defs>`,
    );
    irisFill = `url(#${gradId})`;
  }
  parts.push(`<circle cx="${fmt1(ix)}" cy="${fmt1(irisCy)}" r="${fmt1(irisR * 0.84)}" fill="${irisFill}" />`);
  const bandR = irisR * 0.84;
  const cut = bandR * IRIS_BAND_CUT;
  const half = pySqrt(bandR * bandR - cut * cut);
  parts.push(
    `<path d="M ${fmt2(ix - half)} ${fmt2(irisCy - cut)} A ${fmt2(bandR)} ${fmt2(bandR)} 0 0 1 ` +
      `${fmt2(ix + half)} ${fmt2(irisCy - cut)} Z" fill="${shade(eye_color, IRIS_BAND_SHADE)}" />`,
  );
  parts.push(
    `<circle cx="${fmt1(ix)}" cy="${fmt1(irisCy + irisR * 0.1)}" r="${fmt1(irisR * pupil_ratio)}" ` +
      `fill="${shade(eye_color, 0.18)}" />`,
  );
  if (soft) {
    // Light bouncing up into the lower iris, a glow that fades out before the
    // iris's edge, kept inside the iris disc by its own clip.
    const sideId = side < 0 ? "l" : "r";
    const clip = `iris-clip-${sideId}`;
    const glow = `iris-glow-${sideId}`;
    parts.push(
      `<defs><clipPath id="${clip}"><circle cx="${fmt1(ix)}" cy="${fmt1(irisCy)}" r="${fmt1(irisR * 0.84)}" /></clipPath>` +
        `<radialGradient id="${glow}"><stop offset="0" stop-color="${tint(eye_color, 0.5)}" stop-opacity="0.60" />` +
        `<stop offset="1" stop-color="${tint(eye_color, 0.5)}" stop-opacity="0" /></radialGradient></defs>` +
        `<ellipse cx="${fmt1(ix)}" cy="${fmt1(irisCy + irisR * 0.5)}" rx="${fmt1(irisR * 0.62)}" ` +
        `ry="${fmt1(irisR * 0.4)}" fill="url(#${glow})" clip-path="url(#${clip})" />`,
    );
  }
  if (stretch) parts.push("</g>");
  const up = f.iris_aspect;
  parts.push(
    `<circle cx="${fmt1(ix - irisR * 0.42)}" cy="${fmt1(irisCy - irisR * 0.48 * up)}" r="${fmt1(irisR * 0.34)}" fill="white" />`,
  );
  parts.push(
    `<circle cx="${fmt1(ix + irisR * 0.35)}" cy="${fmt1(irisCy + irisR * 0.42 * up)}" r="${fmt1(irisR * 0.16)}" ` +
      `fill="white" opacity="0.85" />`,
  );
  parts.push("</g>");

  const path = (pts: readonly Point[], closed = false): string => {
    const d2 = "M " + pts.map(([x, y]) => `${fmt2(ex + side * x)} ${fmt2(ey + y)}`).join(" L ");
    return closed ? d2 + " Z" : d2;
  };

  const edgeW = outlineW(sw, EYE_OUTLINE_W);
  const quads = eyeQuads(er, f);
  parts.push(
    `<path d="${path(lidPoints(quads, 2, 3))}" fill="none" stroke="${OUTLINE}" ` +
      `stroke-width="${fmt2(interiorW(sw, 0.8))}" stroke-linecap="round" />`,
  );
  const lowerN = pyInt(LID_SAMPLES * LOWER_LASH_REACH);
  const q2 = quads[2] as [Point, Point, Point];
  const lowerLash: Point[] = [];
  for (let k = 0; k <= lowerN; k++) lowerLash.push(quadPoint(q2[0], q2[1], q2[2], k / LID_SAMPLES));
  parts.push(
    `<path d="${path(lowerLash)}" fill="none" stroke="${OUTLINE}" ` +
      `stroke-width="${fmt2(edgeW * 0.8)}" stroke-linecap="round" />`,
  );
  parts.push(`<path d="${path(eyeLash(er, f, edgeW, reach), true)}" fill="${OUTLINE}" stroke="none" />`);
  return parts.join("");
}

// How far a closed lid's line sags below its two corners, and where those
// corners sit, both in eye radii measured down from the eye's own center. A
// shut eye in this style is the lash line alone: the lids meet low in the
// aperture, so the line sits below where the open eye's middle was, and bows
// down between the corners the way a relaxed lid does. Picked by render sweep
// against the open eye at chibi scale, judged by whether it reads as the same
// eye shut rather than a new mark on the face.
export const EYE_CLOSED_DROP = 0.3;
export const EYE_CLOSED_SAG = 0.38;

/**
 * `FaceStyle.eyes_closed`: one lash line from the inner corner to the outer.
 *
 * The corners are `_eye_shape`'s own (same width, same tilt), so the shut
 * eye spans exactly what the open one did and a cut between the two reads
 * as a blink rather than as the eye jumping. Same stroke weight as the open
 * aperture's outline, and round caps, as its redrawn lid has.
 */
export function eyeClosed(ex: number, ey: number, er: number, side: number, f: FaceStyle, sw: number): string {
  const w = er * f.eye_width * EYE_ASPECT;
  const tilt = er * f.eye_tilt * 0.3;
  const y = ey + er * EYE_CLOSED_DROP;
  const x0 = ex - side * w;
  const y0 = y + tilt;
  const x1 = ex + side * w;
  const y1 = y - tilt;
  const cx = ex + side * w * 0.05;
  const cy = y + er * EYE_CLOSED_SAG;
  return (
    `<path d="M ${fmt1(x0)} ${fmt1(y0)} Q ${fmt1(cx)} ${fmt1(cy)} ${fmt1(x1)} ${fmt1(y1)}" fill="none" ` +
    `stroke="${OUTLINE}" stroke-width="${fmt2(outlineW(sw, EYE_OUTLINE_W))}" stroke-linecap="round" />`
  );
}

/**
 * A nick with a short cross-tick on one cheek. One line alone reads as a
 * stray stroke at this size; two equal lines read as a cartoon X, so the
 * tick is kept short.
 */
export function scar(sk: Skeleton, side: number): string {
  const r = sk.head_r;
  const cx = sk.head_cx;
  const cy = sk.head_cy;
  const sw = strokeW(sk);

  const line = (x1: number, y1: number, x2: number, y2: number, w: number): string =>
    `<line x1="${fmt1(cx + side * r * x1)}" y1="${fmt1(cy + r * y1)}" ` +
    `x2="${fmt1(cx + side * r * x2)}" y2="${fmt1(cy + r * y2)}" ` +
    `stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(w))}" stroke-linecap="round" opacity="0.6" />`;

  return line(0.52, 0.56, 0.65, 0.35, sw * 0.6) + line(0.55, 0.44, 0.63, 0.49, sw * 0.45);
}

// ---------------------------------------------------------------------------------------------------------
// The blush

// The blush: a fixed pink at an opacity on light skin, and on dark skin a
// warmer, brighter rose a little stronger, reached gradually. The fixed pink
// over dark skin came out a muddy maroon, reading as a bruise rather than a
// flush (`docs/bare-body-plan.md`, step 7). The change starts below the
// lightness of the "light warm" swatch, so every preset shipped so far, all
// lighter than that, keeps the fixed pink exactly.
export const BLUSH = "#e8879a";
export const BLUSH_OPACITY = 0.45;
export const BLUSH_DARK = "#ff8a8a";
export const BLUSH_DARK_OPACITY = 0.6;
export const BLUSH_LIGHT_L = 0.7;
export const BLUSH_DARK_L = 0.2;

/** The blush's colour and opacity on `skin`; see `_BLUSH`. */
export function blush(skin: string): [string, number] {
  const [r, g, b] = hexToRgb01(skin);
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  // The divisor, `0.70 - 0.20`, is a constant that is not zero.
  const t = pyMax(0.0, pyMin(1.0, (BLUSH_LIGHT_L - lum) / (BLUSH_LIGHT_L - BLUSH_DARK_L)));
  if (t === 0.0) return [BLUSH, BLUSH_OPACITY];
  const light = hexToRgb01(BLUSH);
  const dark = hexToRgb01(BLUSH_DARK);
  // `zip(light, dark, strict=True)`: both are three long.
  const mixed = light.map((a, i) => a + ((dark[i] as number) - a) * t) as [number, number, number];
  return [rgb01ToHex(mixed), BLUSH_OPACITY + (BLUSH_DARK_OPACITY - BLUSH_OPACITY) * t];
}

// ---------------------------------------------------------------------------------------------------------
// The mouth

// How far an open mouth drops, as a share of its width, and where that stops growing. Up to
// `_MOUTH_DEPTH_FREE` it is the opening itself; past it each further step counts for a
// tenth, so a mouth opened wide stays about as tall as it is wide. Taller than wide
// it reads as a slot or a tongue rather than a mouth, and on a narrow mouth it ran down
// past the chin.
export const MOUTH_DEPTH_FREE = 0.85;
export const MOUTH_DEPTH_SLOPE = 0.1;

/** The drop of an open mouth in widths, for `FaceStyle.mouth_open` = `opening`. */
export function mouthDepthShare(opening: number): number {
  if (opening <= MOUTH_DEPTH_FREE) return opening;
  return MOUTH_DEPTH_FREE + (opening - MOUTH_DEPTH_FREE) * MOUTH_DEPTH_SLOPE;
}

// The inside of an open mouth, one flat dark red (`FaceStyle.mouth_open`).
export const MOUTH_INSIDE = "#6b2f2f";

// Where `_face` draws the mouth, in head radii below the head's centre. Shared
// rather than copied, because the beard is built around the mouth: the moustache
// has to clear the lip and the jaw run has to meet it at the corner, and a beard
// built around its own copy of this number agrees with the face on the day it is
// written and silently stops agreeing the first time the mouth moves.
export const MOUTH_Y = 0.55;

// How much wider the mouth gets at the realistic build, on top of
// `mouth_width`'s own per-character value. Measured off `ref/satoko-real.jpg`
// at the same head-radius scale the eye fixes validated: about 0.334 r across
// against our own 0.18 r (`0.12 * mouth_width * 2` at Satoko's 0.75), a 1.86x
// gap. Build-gated rather than folded into the shared `0.12` or into
// `mouth_width` itself, the same call as the eye aperture's width: the mouth
// was never measured against a reference at chibi, which is locked in, so
// this only widens it at builds partway or all the way to realistic.
export const MOUTH_REALISTIC_WIDEN = 0.85;

// How much further down the mouth sits at the realistic build, in head radii,
// on top of `_MOUTH_Y`. Added at the call site rather than folded into
// `_MOUTH_Y` itself, which the beard also reads (`corner_y`, the moustache
// lozenge, `_jaw_track`); moving that would drag Daizen's and Reinhard's
// beard geometry at both builds along with it.
//
// Picked by a render sweep against `ref/satoko-real.jpg` rather than solved
// from a measured chin position: the chin turned out not to have one stable
// reading to solve against. The jaw's own outline is open at the bottom
// centre on this reference, skin-toned all the way into the neck with no
// line between them, and depending on where the scan stopped it read as
// 0.226 r above "the chin" in one pass and 0.508 r above it in another, from
// the same image. Full-face comparisons at matched scale settle it instead:
// 0.18 lands the mouth and nose where the reference has them relative to
// the jaw actually visible in frame, without the two crowding each other.
export const MOUTH_REALISTIC_DROP = 0.18;

// ---------------------------------------------------------------------------------------------------------
// The nose

// The nose, a pair of short marks angling in toward the centre, measured off
// `ref/satoko-real.jpg` for the retired adult build at head-radius scale (the
// outer end 0.094 r out, the inner 0.028 r, a drop of 0.033 r) and sitting with
// the mouth (`_MOUTH_REALISTIC_DROP`). It grows in with face maturity, length,
// weight and all, so it never pops in; at 0 there is no nose, as the chibi
// canon draws none.
export const NOSE_Y = 0.36;
export const NOSE_OUT = 0.094;
export const NOSE_IN = 0.028;
export const NOSE_DROP = 0.033;

/**
 * How far below the head's centre the nose's lowest point sits, in head
 * radii: with the mouth, which drops as the face grows.
 */
export function noseY(sk: Skeleton): number {
  return NOSE_Y + MOUTH_REALISTIC_DROP * faceBuild(sk);
}

/** The nose as a single small dot, where the ticks' lowest point would be. */
export function noseDot(sk: Skeleton, sw: number): string {
  return (
    `<circle cx="${fmt2(sk.head_cx)}" cy="${fmt2(sk.head_cy + sk.head_r * noseY(sk))}" ` +
    `r="${fmt2(interiorW(sw, 0.9) * 0.62)}" fill="${OUTLINE}" opacity="0.8" />`
  );
}

export function nose(sk: Skeleton, sw: number): string {
  const m = sk.face_maturity;
  const cx = sk.head_cx;
  const cy = sk.head_cy;
  const r = sk.head_r;
  const y = cy + r * noseY(sk);
  const out = r * NOSE_OUT * m;
  const inn = r * NOSE_IN * m;
  const drop = r * NOSE_DROP * m;
  const parts: string[] = [];
  for (const side of [-1, 1]) {
    parts.push(
      `<path d="M ${fmt2(cx + side * out)} ${fmt2(y - drop)} ` +
        `Q ${fmt2(cx + (side * (out + inn)) / 2)} ${fmt2(y - drop * 0.4)} ${fmt2(cx + side * inn)} ${fmt2(y)}" ` +
        `fill="none" stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(sw, 0.8 * m))}" ` +
        `opacity="0.75" stroke-linecap="round" />`,
    );
  }
  return parts.join("");
}

// ---------------------------------------------------------------------------------------------------------
// The face

// How far inside the face's edge an eye's outermost ink (the lash's flick) has to
// stay, in head radii (`_face`, `_eye_lash`).
export const EYE_EDGE_CLEAR = 0.03;

export function face(sk: Skeleton, p: CharacterParams): string {
  const r = sk.head_r;
  const cx = sk.head_cx;
  const cy = sk.head_cy;
  const [eyeDx, eyeY, eyeR, f] = eyePlacement(sk, p);
  // How far out from an eye's centre its lash may reach: the face's edge at the
  // eye's height, less `_EYE_EDGE_CLEAR`.
  const edge = headEdgeX(pyDiv(eyeY - cy, r), faceBuild(sk)) * r;
  const reach = edge - eyeDx - EYE_EDGE_CLEAR * r;
  const sw = strokeW(sk);
  const pupilRatio = 0.4 + PUPIL_REALISTIC_GROW * eyeBuild(sk);
  const parts: string[] = [];

  for (const side of [-1, 1]) {
    const ex = cx + side * eyeDx;
    if (!truthy(f.brows_over_hair)) parts.push(brow(sk, p, side));
    if (truthy(f.eyes_closed)) {
      parts.push(eyeClosed(ex, eyeY, eyeR, side, f, sw));
    } else {
      parts.push(eye(ex, eyeY, eyeR, side, f, p.eye_color, sw, pupilRatio, reach, isSoft(p)));
    }
  }

  if (truthy(f.nose_dot)) {
    parts.push(noseDot(sk, sw));
  } else if (sk.face_maturity > 0.0) {
    parts.push(nose(sk, sw));
  }

  const mouthY = cy + r * (MOUTH_Y + MOUTH_REALISTIC_DROP * faceBuild(sk) + f.mouth_drop);
  const mouthHalf = r * 0.12 * f.mouth_width * (1.0 + MOUTH_REALISTIC_WIDEN * faceBuild(sk));
  if (f.mouth_open > 0.0) {
    // Open: the shut mouth's curve is the upper lip, and a second curve below it
    // closes the shape. Filled one flat dark tone, outlined like the rest of the
    // face, with no teeth or tongue drawn.
    const depth = mouthHalf * 2.0 * mouthDepthShare(f.mouth_open);
    parts.push(
      `<path d="M ${fmt1(cx - mouthHalf)} ${fmt1(mouthY)} ` +
        `Q ${fmt1(cx)} ${fmt1(mouthY + r * 0.08 * f.mouth_curve)} ${fmt1(cx + mouthHalf)} ${fmt1(mouthY)} ` +
        `C ${fmt1(cx + mouthHalf * 0.95)} ${fmt1(mouthY + depth * 1.35)} ` +
        `${fmt1(cx - mouthHalf * 0.95)} ${fmt1(mouthY + depth * 1.35)} ${fmt1(cx - mouthHalf)} ${fmt1(mouthY)} Z" ` +
        `fill="${MOUTH_INSIDE}" stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(sw, 0.85))}" ` +
        `stroke-linecap="round" stroke-linejoin="round" />`,
    );
  } else {
    parts.push(
      `<path d="M ${fmt1(cx - mouthHalf)} ${fmt1(mouthY)} ` +
        `Q ${fmt1(cx)} ${fmt1(mouthY + r * 0.08 * f.mouth_curve)} ${fmt1(cx + mouthHalf)} ${fmt1(mouthY)}" ` +
        `fill="none" stroke="${OUTLINE}" stroke-width="${fmt2(interiorW(sw, 0.85))}" stroke-linecap="round" />`,
    );
  }

  if (f.blush > 0) {
    const blushParts: string[] = [];
    for (const side of [-1, 1]) {
      // Below and outside the eyes, which sit lower than they used to;
      // at the old height the blush clipped under the lower lids.
      const bx = cx + side * r * 0.58;
      const blushRy = r * 0.09;
      // And never over the eye itself: a face with large or low eyes would have the
      // blush tint the iris and the lower lid, so it starts below the lower lash line.
      const by = pyMax(cy + r * 0.44, eyeY + eyeR * f.eye_lower_lid + sw + blushRy);
      const [color, opacity] = blush(p.skin_tone);
      if (isSoft(p)) {
        // The same pink, fading to nothing at the ellipse's edge, a little wider
        // so the flush is as large as the hard one looked.
        if (side < 0) {
          blushParts.push(
            `<defs><radialGradient id="blush-grad"><stop offset="0" stop-color="${color}" ` +
              `stop-opacity="${fmt2(pyMin(1.0, opacity * f.blush * 1.5))}" />` +
              `<stop offset="1" stop-color="${color}" stop-opacity="0" /></radialGradient></defs>`,
          );
        }
        blushParts.push(
          `<ellipse cx="${fmt1(bx)}" cy="${fmt1(by)}" rx="${fmt1(r * 0.21)}" ry="${fmt1(blushRy * 1.35)}" ` +
            `fill="url(#blush-grad)" />`,
        );
        continue;
      }
      blushParts.push(
        `<ellipse cx="${fmt1(bx)}" cy="${fmt1(by)}" rx="${fmt1(r * 0.16)}" ry="${fmt1(blushRy)}" ` +
          `fill="${color}" opacity="${fmt2(opacity * f.blush)}" />`,
      );
    }
    // Kept inside the face: on a narrow face the blush reaches past the cheek's edge and
    // would tint the hair behind it, so it is clipped to the face's own shape. The clip
    // runs to the middle of the outline's stroke, so the outline is drawn again over it:
    // the blush then stops at the line instead of lightening the line's inner half.
    const [fill, silhouette, underChin] = headPaths(sk);

    const line = (d: string, weight: number): string =>
      `<path d="${d}" fill="none" stroke="${OUTLINE}" stroke-linecap="round" ` +
      `stroke-width="${fmt2(outlineW(sw, weight))}" />`;

    parts.push(
      `<defs><clipPath id="blush-clip"><path d="${fill}" /></clipPath></defs>` +
        `<g clip-path="url(#blush-clip)">${blushParts.join("")}</g>` +
        `${line(silhouette, 1.0)}${line(underChin, 0.6)}`,
    );
  }

  if (truthy(f.scar_side)) {
    parts.push(scar(sk, f.scar_side > 0 ? 1 : -1));
  }

  return parts.join("");
}
